.home-care strong{font-size:clamp(10px,2.8vw,16px)}
.home-caption{font-size:clamp(8px,2vw,11px)}
.home-caption span{font-family:serif}
/* The spout is aligned over the stream's center. */
.faucet{left:38%;width:23%}.faucet i{right:-68%;width:120%}
.home-caption span{font-size:0;width:12px;height:8px;position:relative;display:block;flex-shrink:0}
.home-caption span:before,.home-caption span:after{content:'';position:absolute;top:0;width:6px;height:6px;border:2px solid #f3acd0;border-radius:50% 50% 30% 50%;transform:rotate(30deg);left:0}
.home-caption span:after{left:5px;transform:rotate(-30deg)}

/* Mobile delivery hardening: keep existing geometry and pointer mechanics. */
.app{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
button{touch-action:manipulation}
#bottle,#peekButton,#tapZone{touch-action:none}
input{-webkit-user-select:text;user-select:text}
@supports(padding:max(0px)){body{padding-left:env(safe-area-inset-left,0px);padding-right:env(safe-area-inset-right,0px)}.app{max-width:min(100%,calc(100dvh * .64))}}
@media(orientation:landscape) and (max-height:550px){.app{max-width:100%}}
/* Keep all home controls inside the same safe-area coordinate system. */
:root{--safe-top:env(safe-area-inset-top,0px);--safe-bottom:env(safe-area-inset-bottom,0px)}
@supports(height:100dvh){.app{height:calc(100dvh - var(--safe-top) - var(--safe-bottom));margin-top:var(--safe-top)}header{top:.4%}body:not([data-screen="home"]) header{top:0}body:not([data-screen="home"]) #app{top:10%;bottom:0}.home-caption{bottom:3.5%}}

