.rules-screen{height:100%;display:flex;flex-direction:column;gap:10px;min-height:0;padding-bottom:5px}.rules-heading{position:relative;padding-right:105px;flex-shrink:0}.rules-heading h1{font-size:clamp(17px,4.8vw,25px);margin:5px 0;line-height:1.4}.rules-heading #back{position:absolute;right:0;top:0;min-height:44px;font-size:12px;padding:7px 10px}.rules-demo{position:relative;flex:1;min-height:115px;max-height:290px;background:linear-gradient(145deg,#fff9fc,#e2f5ff);border:3px solid #fff;border-radius:25px;overflow:hidden;box-shadow:0 4px 12px #cc91b333}.demo-tag{position:absolute;top:10px;left:12px;font-size:10px;color:#a3648c;background:#fff9;border-radius:20px;padding:4px 9px}.rules-copy{flex-shrink:0;text-align:center;border:2px solid #fff;border-radius:20px;background:#fff8fc;padding:10px 12px}.rules-goal{display:inline-block;padding:5px 15px;margin:0 0 7px;border-radius:25px;background:#e5f3ff;color:#52618f;font-size:12px}.rules-copy h2{font-size:clamp(14px,3.9vw,20px);line-height:1.7;margin:0 0 8px}.rules-tip{font-size:12px;line-height:1.65;margin:5px 0 9px}.rules-detail{border-top:1px dashed #e8bad1;padding-top:8px;font-size:10px;line-height:1.7;margin:0}.rules-screen>#start{flex-shrink:0;min-height:52px;font-size:18px}.demo-stream{position:absolute;width:22%;height:86%;left:43%;top:0;background:repeating-linear-gradient(90deg,#a9e2fa99 0 5px,#eefaff 5px 9px);border-radius:0 0 35% 35%;animation:demo-water .6s infinite alternate}.demo-bottle{position:absolute;width:25%;height:55%;object-fit:contain;top:23%;left:41%;animation:demo-shake .55s ease-in-out infinite alternate}.demo-arrows{position:absolute;left:72%;top:30%;font-size:50px;color:#80b5d8}.rules-demo .demo-face{position:absolute;width:72%;height:80%;left:14%;top:3%;bottom:auto;object-fit:contain;transform:none}.demo-hands{position:absolute;width:40%;height:45%;object-fit:contain;top:25%;left:30%;animation:demo-peek 3s ease-in-out infinite}.demo-gesture{position:absolute;bottom:8px;left:3%;right:3%;text-align:center;border-radius:20px;background:#fffc;font-size:12px;padding:5px}.demo-pat{position:absolute;left:62%;top:20%;width:23%;height:30%;object-fit:contain;animation:demo-pat 3s infinite}.demo-notes{position:absolute;top:15%;left:8%;font-size:22px;color:#dc84b0;animation:demo-notes 3s infinite}.countdown-overlay{position:absolute;inset:0;z-index:30;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#fff1f8f5;border-radius:24px;gap:15px;touch-action:none}.countdown-number{font-size:clamp(100px,28vw,170px);line-height:1.2;font-weight:900;color:#eb8dbb;text-shadow:3px 5px 0 white,0 8px 0 #c66d9b;animation:countdown-pop .55s ease-out both}.countdown-start{font-size:clamp(55px,16vw,94px);color:#7cbbdf}.countdown-sparkles{font-size:40px;color:#edadd0;animation:demo-water .6s infinite alternate}.countdown-overlay p{font-size:14px}.countdown-back{min-height:44px}.countdown-overlay~*{pointer-events:none}
